import sqlite3, json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
SOURCE_SKILL = "tau2Airline"

# Load all valid flights into memory
flights = {}
for r in conn.execute("SELECT * FROM flights WHERE source_skill=?", (SOURCE_SKILL,)):
    dep = r['departure_time']
    arr = r['arrival_time']
    if not dep or not arr:
        continue
    dates_raw = json.loads(r['dates_json'] or '{}')
    flights[r['flight_id']] = {
        'flight_number': r['flight_id'],
        'origin': r['origin'],
        'destination': r['destination'],
        'dep': dep,
        'arr': arr,
        'dates': dates_raw,
    }
conn.close()

# Collect all unique dates across all flights
all_dates = set()
for f in flights.values():
    all_dates.update(f['dates'].keys())

origin = 'SFO'
destination = 'JFK'

# For each date, check if a one-stop connection exists
dates_with_options = {}

for date in sorted(all_dates):
    options = []
    for fid1, f1 in flights.items():
        if f1['origin'] != origin:
            continue
        if date not in f1['dates']:
            continue
        if f1['dates'][date].get('status') != 'available':
            continue

        stopover = f1['destination']
        arr_time1 = f1['arr']

        # Handle +1 day connections
        if '+1' in arr_time1:
            day = int(date.split('-')[2]) + 1
            date2 = f"{date[:8]}{day:02d}"
            arr_clean = arr_time1.replace('+1', '').strip()
        else:
            date2 = date
            arr_clean = arr_time1

        for fid2, f2 in flights.items():
            if f2['origin'] != stopover or f2['destination'] != destination:
                continue
            if date2 not in f2['dates']:
                continue
            if f2['dates'][date2].get('status') != 'available':
                continue
            if f2['dep'] >= arr_clean:
                p1 = {k: v for k, v in f1['dates'][date].get('prices', {}).items() if k in ('business', 'economy', 'basic_economy')}
                p2 = {k: v for k, v in f2['dates'][date2].get('prices', {}).items() if k in ('business', 'economy', 'basic_economy')}
                s1 = {k: v for k, v in f1['dates'][date].get('available_seats', {}).items() if k in ('business', 'economy', 'basic_economy')}
                s2 = {k: v for k, v in f2['dates'][date2].get('available_seats', {}).items() if k in ('business', 'economy', 'basic_economy')}
                options.append({
                    'leg1': f1, 'leg2': f2,
                    'date1': date, 'date2': date2,
                    'p1': p1, 'p2': p2,
                    's1': s1, 's2': s2,
                })

    if options:
        dates_with_options[date] = options

if not dates_with_options:
    print("No one-stop SFO -> JFK flights found on any date.")
else:
    print(f"Found one-stop SFO → JFK availability on {len(dates_with_options)} date(s):\n")
    for date, options in sorted(dates_with_options.items()):
        print(f"{'='*60}")
        print(f"  DATE: {date}  ({len(options)} option(s))")
        print(f"{'='*60}")
        for i, opt in enumerate(options, 1):
            l1 = opt['leg1']
            l2 = opt['leg2']
            # Combined prices
            combined_be = (opt['p1'].get('basic_economy',0) or 0) + (opt['p2'].get('basic_economy',0) or 0)
            combined_ec = (opt['p1'].get('economy',0) or 0) + (opt['p2'].get('economy',0) or 0)
            combined_bu = (opt['p1'].get('business',0) or 0) + (opt['p2'].get('business',0) or 0)
            print(f"  Option {i}:")
            print(f"    Leg 1: {l1['flight_number']}  {l1['origin']} → {l1['destination']}  Depart: {l1['dep']}  Arrive: {l1['arr']}  (Date: {opt['date1']})")
